export const getBankLogo = (banco) => {
    switch (banco.toLowerCase()) {

        case "bancolombia":
            return "data:image/jpeg;base64,";

        case "davivienda":
            return "data:image/png;base64,";;

        case "bbva":
            return "data:image/png;base64,";

        case "banco de bogotá":
        case "banco de bogota":
            return "data:image/jpeg;base64,";

        case "banco de occidente":
            return "data:image/png;base64,";

        case "banco av villas":
        case "av villas":
            return "data:image/png;base64,";

        case "banco popular":
            return "data:image/png;base64,";

        case "banco agrario de colombia":
        case "banco agrario":
            return "https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcT376v_wS9NRczIzOnf4y7LN0mrVN0P7k0FBA&s";

        case "banco caja social":
        case "caja social":
            return "data:image/jpeg;base64,";

        case "banco pichincha":
        case "pichincha":
            return "data:image/jpeg;base64,";

        case "itaú":
        case "itau":
            return "data:image/png;base64,";

        case "scotiabank colpatria":
        case "colpatria":
            return "data:image/png;base64,";

        default:
            return "https://cdn-icons-png.flaticon.com/512/149/149071.png";
    }
};